storage:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /enc_space/{f} { allow get: if f == 'a b.txt'; }
    match /enc_space_raw/{f} { allow get: if f == 'a%20b.txt'; }
    match /enc_plus/{f} { allow get: if f == 'a b.txt'; }
    match /enc_plus_raw/{f} { allow get: if f == 'a+b.txt'; }
    match /enc_slash_one/{f} { allow get: if f == 'a/b.txt'; }
    match /enc_slash_two/{a}/{b} { allow get: if a == 'a' && b == 'b.txt'; }
    match /enc_pct/{f} { allow get: if f == 'a%b.txt'; }
    match /enc_utf8/{f} { allow get: if f == 'é.txt'; }
    match /enc_path/{f} { allow get: if request.path == /b/demo-oracle.appspot.com/o/enc_path/a%20b.txt; }
    match /rest_string/{rest=**} { allow get: if string(rest) == '/a/b.txt'; }
    match /rest_string_one/{rest=**} { allow get: if string(rest) == '/a'; }
    match /rest_string_enc/{rest=**} { allow get: if string(rest) == '/a%20b'; }
  }
}

firestore:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /enc_space/{id} { allow get: if id == 'a b'; }
    match /enc_space_raw/{id} { allow get: if id == 'a%20b'; }
    match /rest_string/{rest=**} { allow get: if string(rest) == '/a/b'; }
  }
}
